drop policy if exists "Admins can view all member reports" on public.user_reports;
create policy "Admins can view all member reports" on public.user_reports for select to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
drop policy if exists "Admins can update report status" on public.user_reports;
create policy "Admins can update report status" on public.user_reports for update to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin') with check ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
grant update (status) on public.user_reports to authenticated;
drop policy if exists "Admins can view profiles for moderation" on public.profiles;
create policy "Admins can view profiles for moderation" on public.profiles for select to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create table if not exists public.user_report_audit (id uuid primary key default gen_random_uuid(), report_id uuid not null references public.user_reports(id) on delete cascade, actor_id uuid references auth.users(id) on delete set null, old_status text not null, new_status text not null, created_at timestamptz not null default now());
alter table public.user_report_audit enable row level security;
revoke all on public.user_report_audit from anon, public;
grant select on public.user_report_audit to authenticated;
drop policy if exists "Admins can view report audit" on public.user_report_audit;
create policy "Admins can view report audit" on public.user_report_audit for select to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create or replace function public.log_user_report_status_change() returns trigger language plpgsql security definer set search_path = '' as $function$ begin if old.status is distinct from new.status then insert into public.user_report_audit(report_id, actor_id, old_status, new_status) values (new.id, auth.uid(), old.status, new.status); end if; return new; end; $function$;
revoke all on function public.log_user_report_status_change() from public, anon, authenticated;
drop trigger if exists user_report_status_audit_trigger on public.user_reports;
create trigger user_report_status_audit_trigger after update of status on public.user_reports for each row execute function public.log_user_report_status_change();
create index if not exists user_reports_status_created_at_idx on public.user_reports(status, created_at desc);
create index if not exists user_report_audit_report_created_at_idx on public.user_report_audit(report_id, created_at desc);